import { useEffect, useRef, useState } from "react";
import { StreamMockResponse } from "@/lib/mockResponse";
import ReactMarkdown from "react-markdown";
import { Prism as SyntaxHighlighter } from "@components/prism-highlighter";
import { gfm } from "remark-gfm";
import { CopyButton } from "@/components/ui/copy-button";
import { Button } from "@/components/ui/button";
import { Loader2, Edit2, Trash2, ThumbsUp, ThumbsDown } from "lucide-react";
import { cn } from "@/lib/utils";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  isStreaming?: boolean;
  timestamp?: number;
}

const MessageList = ({ messages }: { messages: Message[] }) => {
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [stream, setStream] = useState<(() => void) | null>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    // TODO: Show toast or feedback
  };

  const handleRegenerate = (messageId: string) => {
    // TODO: Implement regeneration
  };

  const handleFeedback = (messageId: string, type: "up" | "down") => {
    // TODO: Implement feedback
  };

  return (
    <div className="flex-1 overflow-y-auto p-4 space-y-4">
      {messages.map((message) => (
        <div
          key={message.id}
          className={`flex ${
            message.role === "user" ? "justify-end" : "justify-start"
          }`}
        >
          <div
            className={cn(
              "max-w-[80%] rounded-3xl p-4 px-6 py-3",
              message.role === "user"
                ? "bg-primary text-primary-foreground"
                : "bg-accent/20 border border-accent/30 text-foreground"
            )}
          >
            {message.isStreaming ? (
              <div className="flex flex-col">
                <div className="prose prose-sm max-w-none">
                  {/* Streaming content will be updated via ref */}
                  <span id={`stream-${message.id}`} className="break-words" />
                </div>
                <div className="flex items-center space-x-2 mt-2">
                  <Loader2 className="h-4 w-4" /> <span className="text-xs">Thinking...</span>
                </div>
              </div>
            ) : (
              <>
                <ReactMarkdown
                  remarkPlugins={[gfm]}
                  components={{
                    code({ node, inline, className, children, ...props }) {
                      const match = /language-(\w+)/.exec(className || "");
                      return !inline && match ? (
                        <SyntaxHighlighter
                          className="language-" + match[1]
                          style={{ padding: 16, borderRadius: 4 }}
                          children={String(children).replace(/\n$/, "")}
                        />
                      ) : (
                        <code
                          className={cn(
                            "bg-muted px-1.5 py-0.5 rounded",
                            inline ? "" : "block overflow-x-auto"
                          )}
                          {...props}
                        >
                          {children}
                        </code>
                      );
                    },
                    // Add a wrapper for code blocks to include copy button
                    pre({ children, ...props }) {
                      return (
                        <div className="relative">
                          {children}
                          <CopyButton
                            text={String(children).replace(/\n$/, "")}
                            className="absolute top-2 right-2"
                          />
                        </div>
                      );
                    },
                  }}
                >
                  {message.content}
                </ReactMarkdown>
                <div className="flex items-center space-x-2 mt-2 text-xs text-muted-foreground">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleCopy(message.content)}
                  >
                    <CopyButton className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleRegenerate(message.id)}
                  >
                    <Edit2 className="h-4 w-4" />
                  </Button>
                  <div className="flex items-center space-x-1">
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => handleFeedback(message.id, "up")}
                    >
                      <ThumbsUp className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => handleFeedback(message.id, "down")}
                    >
                      <ThumbsDown className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      ))}
      <div ref={messagesEndRef} />
    </div>
  );
};

export default MessageList;

import * as React from "react"
import { Check, Copy } from "lucide-react"
import { cn } from "@/lib/utils"

interface CopyButtonProps {
  text: string
  className?: string
}

const CopyButton = React.forwardRef<
  HTMLButtonElement,
  CopyButtonProps
>(({ text, className }, ref) => {
  const [copied, setCopied] = React.useState(false)

  const handleCopy = () {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <button
      ref={ref}
      className={cn(
        "flex items-center gap-1.5 h-8 w-8 rounded-md bg-muted px-2.5 text-sm text-muted-foreground ring-offset-background transition-colors hover:bg-accent/20 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
        className
      )}
      onClick={handleCopy}
      aria-label="Copy to clipboard"
    >
      {!copied ? (
        <Copy className="h-4 w-4" aria-hidden="true" />
      ) : (
        <Check className="h-4 w-4" aria-hidden="true" />
      )}
    </button>
  )
})
CopyButton.displayName = "CopyButton"

export { CopyButton }

import { Highlighter } from "prism-react-renderer";
import React from "react";

type Props = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  defaultLanguage?: string;
};

const PrismHighlighter = ({
  children,
  className,
  style,
  defaultLanguage = "",
}: Props) => {
  return (
    <Highlighter
      {...{
        code: typeof children === "string" ? children : "",
        language: defaultLanguage,
        theme: {
          plain: {
            backgroundColor: "transparent",
            color: "inherit",
            ...style,
          },
          styles: [],
        },
      }}
    >
      {({ className, style, tokens, getLineProps, getTokenProps, getPreProps }) => (
        <pre
          className={className}
          style={{
            backgroundColor: "transparent",
            ...style,
            overflow: "auto",
            padding: 16,
            borderRadius: 4,
          }}
          {...getPreProps()}
        >
          {tokens.map((line, i) => (
            <div
              {...getLineProps({ line, key: i })}
              style={{ ...(style || {}), ...(line.className ? { ...style } : {}) }}
            >
              {line.map((token, j) => (
                <span
                  key={j}
                  {...getTokenProps({ token, line, j })}
                  style={{
                    ...(style || {}),
                    ...(token.className ? { ...style } : {}),
                  }}
                >
                  {token.value}
                </span>
              ))}
            </div>
          ))}
        </pre>
      )}
    </Highlighter>
  );
};

export default PrismHighlighter;

import { useState, useRef, useEffect } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuCheckboxItem } from "@/components/ui/dropdown-menu";
import { Paperclip, ArrowUp, Menu, CircleHelp } from "lucide-react";
import { Separator } from "@/components/ui/separator";

const models = ["GPT 5.5", "GPT 4o", "Claude 3 Opus"];
const efforts = ["Medium", "High"];

const PromptInput = ({ onSubmit, onAttach }: { onSubmit: (prompt: string) => void; onAttach?: () => void }) => {
  const [prompt, setPrompt] = useState("");
  const [model, setModel] = useState(models[0]);
  const [effort, setEffort] = useState(efforts[0]);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (prompt.trim()) {
      onSubmit(prompt);
      setPrompt("");
    }
  };

  const handleKeyDown = (e: React.KeyEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-3">
      <div className="flex items-start space-x-3">
        {/* Left actions: Attach */}
        <Button
          variant="outline"
          size="icon"
          onClick={onAttach}
          aria-label="Attach files"
        >
          <Paperclip className="h-4 w-4" />
        </Button>

        {/* Textarea */}
        <textarea
          ref={textareaRef}
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Ask anything..."
          className="flex-1 min-h-[60px] rounded-md border border-input bg-background px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 resize-none"
          rows={1}
          maxRows={6}
        />

        {/* Right actions: Send */}
        <Button
          type="submit"
          disabled={!prompt.trim()}
          variant="default"
          size="icon"
          aria-label="Send message"
        >
          <ArrowUp className="h-4 w-4" />
        </Button>
      </div>

      {/* Model and Effort selectors */}
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <div className="flex items-center space-x-2">
          <Button variant="outline" size="icon" aria-label="Model">
            <Menu className="h-4 w-4" />
            <span className="ml-2">{model}</span>
          </Button>
          <DropdownMenu align="end" className="ml-2">
            <DropdownMenuTrigger className="p-1 rounded-hover">
              <Button variant="outline" size="icon">
                <Menu className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-48">
              {models.map((m) => (
                <DropdownMenuItem key={m} onClick={() => setModel(m)}>
                  {m}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        <div className="flex items-center space-x-2">
          <Button variant="outline" size="icon" aria-label="Effort level">
            <CircleHelp className="h-4 w-4" />
            <span className="ml-2">{effort}</span>
          </Button>
          <DropdownMenu align="end" className="ml-2">
            <DropdownMenuTrigger className="p-1 rounded-hover">
              <Button variant="outline" size="icon">
                <CircleHelp className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-36">
              {efforts.map((e) => (
                <DropdownMenuItem key={e} onClick={() => setEffort(e)}>
                  {e}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </form>
  );
};

export default PromptInput;

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { MessageSquare, BotMessageSquare } from "lucide-react";

const EmptyState = () => {
  return (
    <div className="flex flex-col items-center justify-center min-h-[calc(100vh-4rem)] p-6 text-center bg-empty-state">
      <div className="mb-6">
